489	                action === 'close' ? gatedPrinterAction('close') : printerAction(action, id, extra)
490	              } />
491	            </div>
492	          )}
493	          {notConfigured && connectionPhase && view !== 'setup' ? (
494	            <p className="printer-setup-explanation">
495	              Need help? <button type="button" className="printer-link-button" onClick={openSetup}>Set up the agent</button>
496	            </p>
497	          ) : notConfigured ? (
498	            body(offerManualPrinterSetup ? () => gatedPrinterAction('manual_setup') : undefined)
499	          ) : (
500	            <MessageList
501	              messages={state.messages}
502	              attachments={state.attachments}
503	              streamingMessageId={state.streamingMessageId}
504	              // In this panel a tool's result is the card it draws, so only a
505	              // change to confirm, or one that failed, is worth a card of its
506	              // own. A printer the model named wrongly is its to explain.
507	              toolActivities={state.toolActivities.filter(
508	                (activity) => activity.tool === 'printer_change' && (activity.requiresApproval || activity.state === 'failed'),
509	              )}
510	              renderActivity={(activity) =>
511	                activity.tool === 'printer_change' ? (
512	                  <PrinterChangeCard activity={activity} onDecision={sendToolDecision} />
513	                ) : undefined
514	              }
515	              builds={[]}
516	              exportedCopies={[]}
517	              physicalPrints={[]}
518	              changes={[]}
