520	              printerActivityText={session ? workingText(session.mode) : undefined}
521	              onPrinterAction={(action, id, tap) => {
522	                const extra: Record<string, string> = {};
523	                if (tap.blockId) extra.blockId = tap.blockId;
524	                if (tap.note) extra.note = tap.note;
525	                printerAction(action, id, extra);
526	              }}
527	              answeredState={false}
528	              onRetry={(messageId) => client.send('retry_message', { messageId })}
529	              onToolDecision={sendToolDecision}
530	              onToolCancel={sendToolCancel}
531	            />
532	          )}
533	          {!notConfigured && !connectionPhase && session && (
534	            <>
535	              <PrinterChipRow
536	                canAdd={session.canAdd}
537	                disabled={busy}
538	                onAdd={() => printerAction('add')}
539	                onReject={() => printerAction('reject', '', { note: rejectedNote(session.facts.printer.name) })}
540	              />
541	            </>
542	          )}
543	          {!notConfigured && (
544	            <Composer
545	              disabled={unavailable}
546	              disabledReason={unavailable ? 'The Agent is not available' : undefined}
547	              placeholder={session ? placeholder(session) : undefined}
548	              photoButton
549	              streaming={streaming}
550	              attachments={stagedAttachments}
551	              onSend={(text) => {
552	                setPrinterDraftText('');
553	                sendMessage(text);
554	              }}
555	              onStop={() => {
556	                if (state.streamingMessageId) client.send('stop_generation', { messageId: state.streamingMessageId });
557	              }}
558	              onAttachFiles={attachFiles}
559	              onRemoveAttachment={removeAttachment}
560	              onDraftChange={setPrinterDraftText}
