1	// Every word the printer panel shows the person, and the notes it records for
2	// the model after a tap. The app sends facts -- sizes, spools, which printer,
3	// what changed -- and the words are made here. The model's instructions are
4	// in printerInstructions.ts.
5	
6	import type {
7	  NetworkPrinterInfo,
8	  PrinterBlock,
9	  PrinterCardInfo,
10	  PrinterSessionPayload,
11	  PrinterSpoolInfo,
12	} from './bridge/protocol';
13	
14	// -- Numbers and lists --------------------------------------------------------
15	
16	// "0.4", "0.25", "1.0": two decimals, trailing zeros dropped down to one, as
17	// the printer profiles spell nozzle sizes.
18	export function numberText(value: number): string {
19	  let text = value.toFixed(2);
20	  while (text.length > 3 && text.endsWith('0')) text = text.slice(0, -1);
21	  return text;
22	}
23	
24	export function mm(value: number): string {
25	  return `${numberText(value)} mm`;
26	}
27	
28	// "a, b and c"
29	export function listed(items: string[]): string {
30	  return items.map((item, index) => (index === 0 ? '' : index + 1 === items.length ? ' and ' : ', ') + item).join('');
31	}
32	
33	// "0.2, 0.4, 0.6 and 0.8 mm"
34	export function sizesText(nozzles: number[]): string {
35	  return `${listed(nozzles.map(numberText))} mm`;
36	}
37	
38	function spoolName(spool: PrinterSpoolInfo): string {
39	  return spool.name || spool.material;
40	}
41	
42	// "PLA Matte and PETG", or "none"
43	function spoolsText(spools: PrinterSpoolInfo[]): string {
44	  return spools.length === 0 ? 'none' : listed(spools.map(spoolName));
45	}
46	
47	// What a printer has loaded, as one line: "AMS lite · PLA Matte + 3".
48	export function spoolSummary(ams: string, spools: PrinterSpoolInfo[]): string {
49	  if (spools.length === 0) return ams;
50	  const first = spoolName(spools[0]) + (spools.length > 1 ? ` + ${spools.length - 1}` : '');
51	  return ams ? `${ams} · ${first}` : first;
52	}
53	
54	// -- The panel's fixed words --------------------------------------------------
55	
56	// A likely answer, rather than a standing invitation.
57	export function placeholder(session: PrinterSessionPayload): string {
58	  if (session.connection || session.added?.length || session.mode === 'connect') return 'Ask for help connecting your printer';
59	  return session.mode === 'add'
60	    ? 'e.g. "bambu a1 mini" or "not sure, the small one"'
61	    : 'e.g. "I put a 0.6 nozzle on it" or "loaded black PETG"';
62	}
63	
64	export const ADD_LABEL = 'Add this printer';
65	export const REJECT_LABEL = 'Not this one';
66	
67	// What stands in for a tool-only turn while it still has no words: which
68	// tool the mode's own instructions let the model call. Add's only tool
69	// looks through the printer list; Change's only tool works out and applies
70	// a change, so it does not name a list that mode never shows.
71	export function workingText(mode: PrinterSessionPayload['mode']): string {
72	  return mode === 'add' ? 'Looking through the printer list…' : 'Working on it…';
73	}
74	
75	// The panel's own first line, which the model is shown as having said: the
76	// same promise every time the panel opens.
77	export function opening(session: PrinterSessionPayload): string {
78	  if (session.mode === 'connect') return 'I can help you connect your printer. Ask about the address, LAN mode, or where to find the access code. Enter credentials only in the connection form.';
79	  if (session.mode === 'change') {
80	    const name = session.context?.printer?.name || session.facts.printer.name || 'this printer';
81	    return `This is the ${name}. Tell me what changed on it, or ask anything about it: nozzle, plate, spools. A photo of the part works too.`;
82	  }
83	  return (
84	    'Which printer do you have? Tell me the brand and model, or share a photo of its label. ' +
85	    "Not sure? Tell me what you know, and I'll help you find it."
86	  );
87	}
88	
89	// -- The cards in the thread --------------------------------------------------
90	
91	// Under a printer's name: what the printer reported, or its size.
92	export function cardSubline(card: PrinterCardInfo): string {
93	  const device = card.device;
94	  if (!device) return card.buildVolume;
95	  let text = `${mm(device.nozzle)} nozzle`;
96	  if (device.spools.length > 0) text += ` · ${spoolSummary(device.ams, device.spools)}`;
97	  if (device.reported) text += ' · read from the printer just now';
98	  return text;
99	}
100	
101	// The undo row: "Nozzle set to 0.6 mm", "Spools updated", or both.
102	export function undoText(block: PrinterBlock): string {
103	  const parts: string[] = [];
104	  if (block.changed?.nozzle) parts.push(`Nozzle set to ${mm(block.changed.nozzle.after)}`);
105	  if (block.changed?.spools) parts.push(parts.length > 0 ? 'spools updated' : 'Spools updated');
106	  return parts.join(', ');
107	}
108	
109	// The change card's title.
110	export function changeTitle(nozzle: boolean, spools: boolean): string {
111	  return nozzle && spools ? 'Change nozzle and spools' : nozzle ? 'Change nozzle' : 'Change spools';
112	}
113	
114	// -- What the model is told after a tap ---------------------------------------
115	// Statements of what the person did, never instructions. The app posts them
116	// only when the tap goes through as described.
117	
118	export function rejectedNote(name: string): string {
119	  return `The person said ${name} is not their printer.`;
120	}
121	
122	export function chosenNote(card: PrinterCardInfo): string {
123	  return `Selected ${card.name}. Nozzle choice: ${mm(card.assumed.nozzle)}.`;
124	}
125	
126	// For a network printer the app matched to a model in the list.
127	export function networkNote(printer: NetworkPrinterInfo): string {
128	  const match = printer.match;
129	  if (!match) return '';
130	  const start = `Selected ${match.name} (${printer.serial})`;
131	  return match.reported
132	    ? `${start}, reporting a ${mm(match.nozzle)} nozzle.`
133	    : `${start}. No nozzle size reported; using the ${mm(match.nozzle)} model default.`;
134	}
135	
136	export function undoneNote(block: PrinterBlock): string {
137	  const back: string[] = [];
138	  if (block.changed?.nozzle) back.push(`the nozzle is ${mm(block.changed.nozzle.before)} again`);
139	  if (block.changed?.spools) back.push(`the spools are ${spoolsText(block.changed.spools.before)} again`);
140	  return `The person undid the change: ${listed(back)}.`;
141	}
