56	// One card in the thread, under the message it belongs to.
57	export const PrinterBlockView = memo(function PrinterBlockView({ block, onAction }: PrinterBlockProps) {
58	  if (block.kind === 'tip')
59	    return (
60	      <div className="printer-tip">
61	        <CameraGlyph className="printer-tip-icon" />
62	        <span>
63	          <b>Tip:</b> a photo is the fastest way. Use <b>Photo</b> below, or drop a picture of the printer, its nameplate or the box
64	          into this panel.
65	        </span>
66	      </div>
67	    );
68	
69	  if (block.kind === 'network') {
70	    const found = (block.printers ?? []) as NetworkPrinterInfo[];
71	    return (
72	      <div className="printer-found">
73	        <p className="printer-found-caption">FOUND ON YOUR NETWORK</p>
74	        {found.map((printer) => (
75	          <div className="printer-row" key={printer.deviceId}>
76	            <span className={printer.online ? 'printer-dot printer-dot-online' : 'printer-dot'} aria-hidden="true" />
77	            <span className="printer-row-name">
78	              {printer.name}
