94	  if (block.kind === 'undo')
95	    return (
96	      <div className="printer-undo">
97	        <span>{undoText(block)}</span>
98	        <span aria-hidden="true"> · </span>
99	        <button type="button" className="printer-link-button" onClick={() => onAction('undo', block.id, { note: undoneNote(block) })}>
