149	// What the person can do with the printer on the card. Both act natively;
150	// adding leads, because the tap is the approval.
151	export const PrinterChipRow = memo(function PrinterChipRow({ canAdd, disabled, onAdd, onReject }: ChipRowProps) {
152	  if (!canAdd) return null;
153	  return (
154	    <div className="printer-chips">
