180	// A change the model worked out from what the person said, stated in words
181	// before anything is saved: the card is where a misreading is caught.
182	export function PrinterChangeCard({
183	  activity,
184	  onDecision,
185	}: {
186	  activity: ToolActivityInfo;
187	  onDecision: (actionId: string, decision: 'approve' | 'reject') => void;
188	}) {
189	  const args = activity.arguments as { nozzle?: number; spools?: PrinterSpoolInfo[]; confirm?: PrinterChangeConfirm };
190	  const confirm = args.confirm;
191	  const printer = confirm?.printer ?? 'this printer';
192	  const nozzle = args.nozzle !== undefined && confirm?.before.nozzle !== undefined;
193	  const spools = args.spools !== undefined && confirm?.before.spools !== undefined;
194	  const keep = nozzle && !spools ? `Keep ${mm(confirm!.before.nozzle!)}` : 'Keep as it is';
195	  const set = nozzle && !spools ? `Set ${mm(args.nozzle!)}` : spools && !nozzle ? 'Set these spools' : 'Set both';
196	
197	  return (
198	    <div className={`printer-change state-${activity.state}`} data-testid={`tool-${activity.actionId}`}>
199	      <div className="printer-change-title">{changeTitle(nozzle, spools)}</div>
200	      {nozzle && (
201	        <>
202	          <div className="printer-change-line">
203	            {mm(confirm!.before.nozzle!)} → <b>{mm(args.nozzle!)}</b> on {printer}
204	          </div>
205	          <div className="printer-change-note">Every project that uses this printer slices for {mm(args.nozzle!)}.</div>
206	        </>
207	      )}
208	      {spools && (
209	        <div className="printer-change-line printer-change-spool-diff">
210	          <div>
211	            <small>Now on {printer}</small>
212	            <SpoolList spools={confirm!.before.spools!} />
213	          </div>
214	          <span aria-hidden="true">→</span>
215	          <div>
216	            <small>After</small>
217	            <SpoolList spools={args.spools!} />
218	          </div>
219	        </div>
220	      )}
221	      {activity.state === 'pending' && (
222	        <div className="printer-change-actions">
223	          <button type="button" className="printer-chip printer-chip-plain" onClick={() => onDecision(activity.actionId, 'reject')}>
224	            {keep}
225	          </button>
226	          <button
227	            type="button"
228	            className="printer-chip printer-chip-primary"
229	            onClick={() => onDecision(activity.actionId, 'approve')}
230	          >
231	            {set}
232	          </button>
233	        </div>
234	      )}
235	      {activity.state === 'rejected' && <div className="printer-change-state">Kept as it was</div>}
236	      {(activity.state === 'approved' || activity.state === 'running') && <div className="printer-change-state">Saving…</div>}
237	      {activity.state === 'failed' && <div className="tool-error">{activity.error?.message ?? 'The change was not saved.'}</div>}
238	    </div>
239	  );
240	}
