1	import { useEffect, useRef, useState } from 'react';
2	import type { PrinterSessionPayload } from '../bridge/protocol';
3	
4	export function PrinterConnection({ session, onAction }: {
5	  session: PrinterSessionPayload;
6	  onAction: (action: string, id?: string, extra?: Record<string, string>) => void;
7	}) {
8	  const connection = session.connection;
9	  const [device, setDevice] = useState('');
