11	// "0.4 mm, Textured PEI Plate · assumed, Bambu PLA Basic · assumed": each
12	// fact the card assumed says so, in the order the pinned card itself states
13	// them.
14	function addedPrinterFacts(added: AddedPrinterInfo): string {
15	  const facts: [string, boolean][] = [
16	    [added.nozzleText, added.nozzleAssumed],
17	    [added.plateText, added.plateAssumed],
18	    [added.filamentText, added.filamentAssumed],
19	  ];
20	  return facts
21	    .filter(([text]) => text)
22	    .map(([text, assumed]) => (assumed ? `${text} · assumed` : text))
23	    .join(', ');
24	}
