26	// Home is the screen before a project: the gallery takes the width that is
27	// left, the printer column is a fixed rail. The page draws no top bar -- the
28	// native shell owns the header above this panel, and a second one here would
29	// duplicate it.
30	export function App({ getTransport }: { getTransport: () => Transport | null }) {
31	  const [state, dispatch] = useReducer(reduce, initialState);
32	
33	  const client = useMemo(
34	    () =>
35	      new BridgeClient({
36	        getTransport,
37	        onEnvelope: (envelope) => dispatch({ kind: 'envelope', envelope }),
38	        onConnectionChange: (connection: ConnectionState, detail?: string) =>
39	          dispatch({ kind: 'connection', state: connection, detail }),
40	      }),
41	    [getTransport],
42	  );
43	
44	  useEffect(() => {
45	    client.start();
46	  }, [client]);
47	
48	  // Each action clears the last refusal first: its message was about the
49	  // previous request, not this one.
50	  const printerActions = useMemo<PrinterActions>(() => {
51	    const send = (type: 'open_printer_settings' | 'rename_printer' | 'remove_printer' | 'connect_printer', payload: object) => {
52	      dispatch({ kind: 'printer_action' });
53	      client.send(type, payload);
54	    };
55	    return {
56	      onConnect: (id) => send('connect_printer', { id }),
57	      onOpenSettings: (id) => send('open_printer_settings', { id }),
58	      onRename: (id, name) => send('rename_printer', name === undefined ? { id } : { id, name }),
59	      onRemove: (id) => send('remove_printer', { id }),
60	    };
61	  }, [client]);
62	
63	  useEffect(() => {
64	    applyAppearance(state.appearance);
65	  }, [state.appearance]);
66	
67	  if (state.connection !== 'connected' && !state.loaded) {
68	    return (
69	      <div className="app connecting">
70	        <h1>Connecting…</h1>
71	        <p>Starting Home.</p>
72	        {state.connectionDetail && (
73	          <details>
74	            <summary>Diagnostics</summary>
75	            <p className="footnote">{state.connectionDetail}</p>
76	          </details>
77	        )}
78	      </div>
79	    );
80	  }
81	
82	  return (
83	    <div className="app">
84	      <main className="gallery">
85	        <header className="gallery-header">
86	          <span className="section-label">Projects</span>
87	          <div className="gallery-actions">
88	            <button type="button" className="button-secondary" onClick={() => client.send('import_project', {})}>
89	              <UploadGlyph />
90	              Import
91	            </button>
92	            <button type="button" className="button-primary" onClick={() => client.send('new_project', {})}>
93	              <PlusGlyph />
94	              New
95	            </button>
96	          </div>
97	        </header>
98	        {state.projects.length === 0 ? (
99	          <p className="empty">No projects yet.</p>
100	        ) : (
101	          <div className="project-grid">
102	            {state.projects.map((project) => (
103	              <ProjectCard
104	                key={project.id}
105	                project={project}
106	                onOpen={(id) => client.send('open_project', { id })}
107	              />
108	            ))}
109	          </div>
110	        )}
111	      </main>
112	      {/* The conversation panel takes this column while it is open; the
113	          shell draws it beside the page, in the same place. */}
114	      {!state.printerPanelOpen && (
115	      <aside className="printer-column">
116	        <span className="section-label">Printers</span>
117	        {state.printerError && (
118	          <p className="printer-error" role="alert">
119	            {state.printerError.message}
120	          </p>
121	        )}
122	        {state.addedPrinter && (
123	          <div className="printer-added-strip">
124	            <span>
125	              <b>{state.addedPrinter.name}</b> added · {addedPrinterFacts(state.addedPrinter)}
126	            </span>
127	            <button
128	              type="button"
129	              className="printer-added-change"
130	              onClick={() => {
131	                const id = state.printers.find((printer) => printer.name === state.addedPrinter?.name)?.id;
132	                if (id) printerActions.onOpenSettings(id);
133	              }}
134	            >
135	              Change
136	            </button>
137	            <button
138	              type="button"
139	              className="printer-added-dismiss"
140	              aria-label="Dismiss"
141	              onClick={() => dispatch({ kind: 'dismiss_added_printer' })}
142	            >
143	              ×
144	            </button>
145	          </div>
146	        )}
147	        {state.printers.map((printer) => (
148	          <PrinterCard
149	            key={printer.id}
150	            printer={printer}
151	            otherNames={state.printers.filter((other) => other.id !== printer.id).map((other) => other.name)}
152	            actions={printerActions}
153	            onLaunchMonitor={(id) => client.send('launch_monitor', { id })}
154	            highlighted={state.addedPrinter?.name === printer.name}
155	          />
156	        ))}
157	        <button type="button" className="add-printer" onClick={() => client.send('add_printer', {})}>
158	          + Add printer
159	        </button>
160	      </aside>
161	      )}
162	    </div>
163	  );
164	}
