20	// At most three candidates: more is a list to read rather than an answer.
21	constexpr std::size_t kMaximumCandidates = 3;
22	
23	// The Add instructions carry every printer, about 28 KB; well above that is
24	// not a prompt the page meant to send.
25	constexpr std::size_t kInstructionsLimit = 256 * 1024;
26	
27	// A note or the opening is a sentence or two; a page that sends more has a
28	// bug, and none of it reaches the thread.
29	constexpr std::size_t kNoteLimit = 2 * 1024;
30	
31	// The note the page wrote for a tap, or empty when it sent none it may.
32	std::string page_note(const json& payload)
33	{
34	    const auto note = payload.find("note");
35	    if (note == payload.end() || !note->is_string())
36	        return {};
37	    const std::string text = note->get<std::string>();
38	    return text.size() <= kNoteLimit ? text : std::string();
39	}
40	
41	std::string number_text(double value)
42	{
43	    std::ostringstream out;
44	    out.precision(2);
45	    out << std::fixed << value;
46	    std::string text = out.str();
47	    while (text.size() > 3 && text.back() == '0')
48	        text.pop_back();
49	    return text;
50	}
51	
52	std::string nozzle_text(double nozzle) { return nozzle > 0. ? number_text(nozzle) + " mm" : std::string(); }
53	
54	// The profile's own spelling of a nozzle size, as the variant is named:
55	// "0.4", "0.25", "1.0".
56	std::string variant_text(double nozzle) { return number_text(nozzle); }
57	
58	// "a, b and c"
59	std::string listed(const std::vector<std::string>& items)
60	{
61	    std::string text;
62	    for (std::size_t i = 0; i < items.size(); ++i)
63	        text += (i == 0 ? "" : i + 1 == items.size() ? " and " : ", ") + items[i];
64	    return text;
65	}
66	
67	// "0.2, 0.4, 0.6 and 0.8 mm"
68	std::string sizes_text(const std::vector<double>& nozzles)
69	{
70	    std::vector<std::string> sizes;
71	    for (double nozzle : nozzles)
72	        sizes.push_back(number_text(nozzle));
73	    return listed(sizes) + " mm";
74	}
75	
76	// A nozzle of null or 0 is the model leaving it unsaid.
77	bool said_nozzle(const json& arguments)
78	{
79	    return arguments.contains("nozzle") && arguments["nozzle"].is_number() && arguments["nozzle"].get<double>() > 0.;
80	}
81	
82	bool ships(const std::vector<double>& nozzles, double nozzle)
83	{
84	    return std::find(nozzles.begin(), nozzles.end(), nozzle) != nozzles.end();
85	}
86	
87	std::string picture_data_url(const std::string& path)
88	{
89	    if (path.empty())
90	        return {};
91	    std::ifstream file(std::filesystem::u8path(path), std::ios::binary);
92	    if (!file.good())
93	        return {};
94	    std::ostringstream bytes;
95	    bytes << file.rdbuf();
96	    const std::string data = bytes.str();
97	    if (data.empty())
98	        return {};
99	    return "data:image/png;base64," + base64_encode(data);
100	}
101	
102	json nullable(const std::string& text) { return text.empty() ? json(nullptr) : json(text); }
103	
104	json spools_json(const std::vector<PrinterSpool>& spools)
105	{
106	    json list = json::array();
107	    for (const PrinterSpool& spool : spools) {
108	        json entry{{"name", spool.name}, {"material", spool.material}};
109	        if (!spool.colour.empty())
110	            entry["colour"] = spool.colour;
111	        list.push_back(std::move(entry));
112	    }
113	    return list;
114	}
115	
116	std::vector<PrinterSpool> spools_of(const json& list)
117	{
118	    std::vector<PrinterSpool> spools;
119	    for (const json& spool : list)
120	        spools.push_back(PrinterSpool{spool.value("name", std::string()), spool.value("material", std::string()),
121	                                      spool.value("colour", std::string())});
122	    return spools;
123	}
124	
125	bool same_spools(const std::vector<PrinterSpool>& lhs, const std::vector<PrinterSpool>& rhs)
126	{
127	    return std::equal(lhs.begin(), lhs.end(), rhs.begin(), rhs.end(), [](const PrinterSpool& a, const PrinterSpool& b) {
128	        return a.name == b.name && a.material == b.material && a.colour == b.colour;
129	    });
130	}
131	
132	// "PLA Matte, PETG" or "none"
133	std::string spools_text(const std::vector<PrinterSpool>& spools)
134	{
135	    std::vector<std::string> names;
136	    for (const PrinterSpool& spool : spools)
137	        names.push_back(spool.name.empty() ? spool.material : spool.name);
138	    return names.empty() ? std::string("none") : listed(names);
139	}
140	
141	std::vector<PrinterSpool> reported_spools(const DiscoveredPrinter& device)
142	{
143	    std::vector<PrinterSpool> spools;
144	    for (const DiscoveredPrinter::Spool& spool : device.spools)
145	        spools.push_back(PrinterSpool{spool.name, spool.material, spool.colour});
146	    return spools;
147	}
