149	// A nozzle the printer reported is settled only when its model ships it.
150	bool reports_nozzle(const DiscoveredPrinter& device, const CatalogPrinter& printer)
151	{
152	    return device.nozzle_diameter > 0. && ships(printer.nozzles, device.nozzle_diameter);
153	}
