241	void PrinterConversation::post_opening(const std::string& text)
242	{
243	    // The first line is the page's to write and the app's to post, once: a
244	    // reloaded page asks again, and the thread already has it.
245	    if (m_opened || text.empty() || text.size() > kNoteLimit)
246	        return;
247	    m_opened                     = true;
248	    const std::string message_id = m_host.post_opening(text);
249	    for (json& entry : m_blocks)
250	        if (entry.value("afterMessageId", std::string()).empty())
251	            entry["afterMessageId"] = message_id;
252	    m_host.session_changed();
253	}
