317	    json added = json::array();
318	    for (const auto& printer : m_added)
319	        added.push_back(json{{"name", printer.name}, {"model", printer.model}, {"connected", printer.connected}});
320	    const json facts{{"printer", json{{"name", m_facts.printer}, {"provenance", m_facts.printer_provenance}}},
321	                     {"nozzle", json{{"size", m_facts.nozzle}, {"provenance", m_facts.nozzle_provenance}}},
322	                     {"plate", json{{"name", m_facts.plate}, {"provenance", m_facts.plate_provenance}}},
