46	// What the packaged profiles offer, one entry per model.
47	struct CatalogPrinter
48	{
49	    std::string         id; // catalogue id, stable for this session
50	    std::string         vendor_id;
51	    std::string         vendor_name;  // the brand, as its vendor file names it
52	    std::string         model_id;     // the profile's own name, which Orca installs by
53	    std::string         model_name;   // that name with the brand not repeated
54	    std::string         device_model_id;
55	    std::string         build_volume; // "180 × 180 × 180 mm"
56	    std::string         picture;
57	    std::string         default_plate; // empty: the profile names none
58	    std::vector<double> nozzles;
59	    // The machine profile's own default filament for each nozzle size, in
60	    // the order of `nozzles`; empty where that profile names none.
61	    std::vector<std::string> filaments;
62	
63	    std::string display_name() const { return vendor_name + " " + model_name; }
64	    std::string filament_for(double nozzle) const
65	    {
66	        for (std::size_t i = 0; i < nozzles.size() && i < filaments.size(); ++i)
67	            if (nozzles[i] == nozzle)
68	                return filaments[i];
69	        return {};
70	    }
